<script lang="ts">
  import { page } from '$app/state';
  import { goto, replaceState } from '$app/navigation';
  import { dev } from '$app/environment';
  import { untrack } from 'svelte';
  import { app } from '$lib/state.svelte';
  import Icon from './Icon.svelte';
  import WelcomeGuide from './WelcomeGuide.svelte';
  let screen=$state<'login'|'activate'|'forgot'|'password'|'sent'|'success'|'invalid'>('login');
  let email=$state(''),password=$state(''),confirmation=$state(''),error=$state(''),busy=$state(false);
  let showPassword=$state(false),showConfirmation=$state(false),token=$state('');
  let flow=$state<'activate'|'forgot'>('activate');
  const activationSteps=['Email PIC','Periksa email','Buat password','Selesai'];
  const step=$derived(flow==='activate'?({activate:1,sent:2,password:3,success:4} as Partial<Record<typeof screen,number>>)[screen]||0:0);
  let target=$state({campus:'',name:'',email:'',purpose:'activate'});
  const longEnough=$derived(password.length>=8),hasNumber=$derived(/[0-9]/.test(password)),hasCapital=$derived(/[A-Z]/.test(password));
  const passwordsMatch=$derived(confirmation.length>0 && password===confirmation);
  const passwordRules=$derived([{label:'Minimal 8 karakter',met:longEnough},{label:'Mengandung angka',met:hasNumber},{label:'Mengandung huruf kapital',met:hasCapital}]);
  const title=$derived(({login:'Selamat datang kembali.',activate:'Aktivasi akun kampus.',forgot:'Lupa password?',password:target.purpose==='forgot'?'Buat password baru.':'Buat password Anda.',sent:'Periksa email Anda.',success:'Password berhasil disimpan.',invalid:'Tautan tidak dapat digunakan.'})[screen]);
  $effect(()=>{const value=page.url.searchParams.get('token');if(value)untrack(()=>{token=value;void inspect();});});
  async function api(operation:string,body:object){const r=await fetch('/api/auth/'+operation,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw new Error(data.message||'Permintaan belum dapat diproses.');return data;}
  function go(next:typeof screen){if(next==='activate'||next==='forgot')flow=next;screen=next;error='';password='';confirmation='';showPassword=false;showConfirmation=false;}
  async function inspect(){busy=true;try{target=await api('inspect',{token});flow=target.purpose==='forgot'?'forgot':'activate';email=target.email;go('password');}catch{go('invalid');}finally{busy=false;}}
  async function submit(){busy=true;error='';try{
    if(screen==='login'){await api('login',{email,password});await app.login('');if(app.session)await goto('/'+app.session.role+'/dashboard');else throw new Error('Sesi belum dapat dimuat.');}
    else if(screen==='password'){if(!longEnough||!hasNumber||!hasCapital)throw new Error('Password minimal 8 karakter, mengandung angka dan huruf kapital.');if(password!==confirmation)throw new Error('Konfirmasi password belum sama.');await api('confirm',{token,password,passwordConfirm:confirmation});go('success');replaceState('/login',{});}
    else{await api('request',{email,purpose:screen==='forgot'?'forgot':'activate'});go('sent');}
  }catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<svelte:head><title>Login - Digitalisasi DEB</title><meta name="robots" content="noindex,nofollow"/></svelte:head>
<main id="main-content" class="login-page auth-page" class:flow-page={step>0 || screen==='success'} class:success-page={screen==='success'} class:password-page={screen==='password'}>
  <section class="login-story"><a class="brand" href="/login"><span class="brand-mark"><Icon name="leaf" size={29}/></span><span>DEB<span class="brand-sub">RUANG TUMBUH BERSAMA</span></span></a><div class="login-copy"><span class="eyebrow light">DIGITALISASI DEB PUTIH</span><h1>Dari kolaborasi,<br/>tumbuh <em>perubahan.</em></h1><p>Satu ruang untuk merawat gagasan, memantau langkah, dan mewujudkan dampak bersama kampus mitra.</p><div class="login-metrics"><div><strong>40</strong><span>Kampus mitra</span></div><div><strong>PB</strong><span>Sumber data tunggal</span></div><div><strong>1</strong><span>Tujuan bersama</span></div></div></div><div class="landscape" aria-hidden="true"><span class="sun"></span><div class="hill back"></div><div class="hill front"></div><svg viewBox="0 0 460 220"><path d="M220 220V70m0 94c-75 0-95-60-95-90 60 0 95 25 95 90Zm0-43c75 0 100-65 100-110-72 0-100 42-100 110Z" fill="#c6e4a7"/><path d="m220 163-65-62m65 23 73-81" fill="none" stroke="#326747" stroke-width="3"/></svg></div><div class="login-footer"><img class="pf-white-logo" src="/logo-pf-white.png" alt="Pertamina Foundation" width="205" height="55"/><span>Untuk masa depan yang berkelanjutan.</span></div></section>
<section class="stage" aria-label="Akses akun">
<div class="stage-top"><span>PORTAL KAMPUS MITRA</span>{#if dev}<a href="/login?qa=1">Akun QA lokal</a>{/if}</div>
<div class="form-wrap">
{#if screen!=='login' && screen!=='success'}<button class="back" onclick={()=>go('login')}>Kembali ke masuk</button>{/if}
{#if step}<nav class="activation-progress" aria-label="Tahapan aktivasi akun"><p>Aktivasi akun <strong>Langkah {step} dari 4</strong></p><ol>{#each activationSteps as label,index}<li class:current={step===index+1} class:complete={step>index+1} aria-current={step===index+1?'step':undefined}><span class="step-number">{#if step>index+1}<Icon name="check" size={14}/>{:else}{index+1}{/if}</span><span>{label}</span></li>{/each}</ol></nav>{/if}
<div class="form-icon"><Icon name={screen==='success'?'check':screen==='invalid'?'alert':'leaf'} size={25}/></div>
<span class="section-label">AKSES AKUN DEB</span><h2>{title}</h2>
{#if ['login','activate','forgot','password'].includes(screen)}
<p class="intro">{screen==='login'?'Masuk menggunakan email PIC dan password akun kampus Anda.':screen==='password'?'Simpan password untuk melanjutkan akses akun kampus.':'Gunakan email PIC yang sudah didaftarkan admin DEB.'}</p>
{#if screen==='password'}<details class="intro-guide"><summary>Baru di DEB? Kenali ruang kerja Anda</summary><WelcomeGuide/></details><div class="account-summary"><Icon name="campus"/><div><strong>{target.campus}</strong><span>{target.name} - {target.email}</span></div></div>{/if}
<form onsubmit={e=>{e.preventDefault();void submit();}}>
{#if screen!=='password'}<label for="real-email">Email PIC</label><input id="real-email" type="email" autocomplete="email" required bind:value={email}/>{/if}
{#if screen==='login'||screen==='password'}
<div class="label-row"><label for="real-password">{screen==='password'?'Password baru':'Password'}</label>{#if screen==='login'}<button class="inline-link" type="button" onclick={()=>go('forgot')}>Lupa password?</button>{/if}</div>
<div class="password-input"><input id="real-password" type={showPassword?'text':'password'} autocomplete={screen==='login'?'current-password':'new-password'} required maxlength="128" aria-describedby={screen==='password'?'password-requirements':undefined} bind:value={password}/><button type="button" aria-label={showPassword?'Sembunyikan password':'Tampilkan password'} aria-pressed={showPassword} onclick={()=>showPassword=!showPassword}><Icon name={showPassword?'eye-off':'eye'} size={18}/></button></div>
{/if}
{#if screen==='password'}<ul id="password-requirements" class="password-rules" aria-label="Persyaratan password">{#each passwordRules as rule}<li class:met={rule.met}><span class="rule-icon" aria-hidden="true">{#if rule.met}<Icon name="check" size={12}/>{:else}<span></span>{/if}</span><span>{rule.label}</span><span class="sr-only">{rule.met?'Terpenuhi':'Belum terpenuhi'}</span></li>{/each}</ul><label for="real-confirm">Konfirmasi password</label><div class="password-input"><input id="real-confirm" type={showConfirmation?'text':'password'} autocomplete="new-password" required maxlength="128" aria-describedby="password-match" bind:value={confirmation}/><button type="button" aria-label={showConfirmation?'Sembunyikan konfirmasi password':'Tampilkan konfirmasi password'} aria-pressed={showConfirmation} onclick={()=>showConfirmation=!showConfirmation}><Icon name={showConfirmation?'eye-off':'eye'} size={18}/></button></div><p id="password-match" class="password-match" class:met={passwordsMatch} class:mismatch={!!confirmation&&!passwordsMatch} aria-live="polite"><span aria-hidden="true">{#if passwordsMatch}<Icon name="check" size={13}/>{/if}</span>{passwordsMatch?'Konfirmasi password cocok.':confirmation?'Konfirmasi password belum cocok.':'Ketik ulang password yang sama.'}</p>{/if}
{#if error}<p class="error" role="alert">{error}</p>{/if}
<button class="primary" disabled={busy || (screen==='password' && (!longEnough || !hasNumber || !hasCapital || !passwordsMatch))}>{busy?'Memproses...':screen==='login'?'Masuk':screen==='password'?'Simpan password':screen==='forgot'?'Kirim tautan pemulihan':'Kirim tautan aktivasi'}<Icon name="arrow" size={18}/></button>
</form>
{#if screen==='login'}<div class="first-time"><span>Pertama kali menggunakan DEB?</span><button onclick={()=>go('activate')}>Aktivasi akun</button></div>{/if}
{:else if screen==='sent'}<p class="intro">Jika email terdaftar dan memenuhi syarat, tautan akan dikirim. Periksa inbox dan folder spam.</p><button class="primary" onclick={()=>go('login')}>Kembali ke masuk</button>
{:else if screen==='success'}<p class="intro">Kenali DEB, lalu masuk dengan email dan password Anda.</p><WelcomeGuide/><button class="primary" onclick={()=>go('login')}>Lanjut ke masuk</button>
{:else}<p class="intro">Tautan mungkin kedaluwarsa, sudah digunakan, atau telah diganti. Minta tautan baru sesuai kebutuhan akun Anda.</p><button class="primary" onclick={()=>go('activate')}>Minta tautan aktivasi</button><button class="inline-link" onclick={()=>go('forgot')}>Pemulihan password</button>{/if}
</div><footer class="stage-footer"><img class="pf-color-logo" src="/logo-pf.png" alt="Pertamina Foundation" width="140" height="37"/><span>Digitalisasi DEB</span></footer>
</section></main>
<style>
