@media(min-width:701px) and (max-height:800px){.form-icon{width:38px;height:38px;margin-bottom:14px}.form-wrap{padding-block:12px}.intro{margin:12px 0 16px}.first-time{margin-top:16px}.primary{margin-top:10px}.login-copy h1{font-size:clamp(34px,5.5vh,44px)}.login-copy{margin-top:5vh}.login-copy>p{margin-top:16px}.login-metrics{margin-top:20px}}
@media(max-width:700px){.auth-page{display:flex;flex-direction:column}.login-story{height:clamp(145px,24dvh,200px);min-height:0;padding:18px 24px;flex-shrink:0}.login-story .brand{font-size:23px}.login-copy{margin-top:14px}.login-copy .eyebrow,.login-copy>p{display:none}.login-copy h1{font-size:clamp(21px,3.2vh,27px);margin-top:0;max-width:270px;line-height:1.15}.landscape{height:170px}.landscape>svg{width:220px;right:-55px}.stage{flex:1;min-height:0;padding:16px 24px}.form-wrap{padding:16px 0}.form-icon{display:none}.section-label{margin-bottom:8px}h2{font-size:24px}.intro{margin:10px 0 16px;font-size:11px}.first-time{margin-top:16px}.stage-footer{padding-top:16px}.primary{margin-top:12px}.stage-top{font-size:9px}.account-summary{margin:12px 0;padding:12px}}

.activation-progress{margin:0 0 24px}.activation-progress>p{display:flex;justify-content:space-between;gap:12px;margin:0 0 15px;font-size:10px;color:#6580a1}.activation-progress strong{color:#1768c0;font-weight:650}.activation-progress ol{list-style:none;padding:0;margin:0;display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.activation-progress li{position:relative;display:flex;flex-direction:column;align-items:center;gap:8px;color:#7c8fa7;font-size:9px;text-align:center;line-height:1.4}.activation-progress li:not(:last-child):after{content:'';position:absolute;left:calc(50% + 19px);right:calc(-50% + 11px);top:15px;height:2px;background:#d9e4f2}.step-number{width:32px;height:32px;border-radius:50%;display:grid;place-items:center;background:#edf2f8;border:1px solid #d4e0ee;color:#7b91ad;font-size:11px;font-weight:650}.activation-progress li.current{color:#155fb9;font-weight:700}.current .step-number{background:#176bd6;border-color:#176bd6;color:white;box-shadow:0 0 0 4px #e7f1ff}.activation-progress li.complete{color:#23764f}.complete .step-number{background:#e7f6ee;border-color:#b6ddc9;color:#23764f}.activation-progress li.complete:after{background:#a1d3bc}.flow-page .form-icon{display:none}.flow-page .back{margin-bottom:18px}.flow-page .intro{margin:12px 0 17px}
@media(max-width:700px){.flow-page .login-story{height:100px;min-height:100px;padding-block:18px}.flow-page .login-copy{display:none}.flow-page .landscape{height:120px}.flow-page .form-wrap{padding-block:12px}.activation-progress{margin-bottom:18px}.flow-page .account-summary{margin:12px 0}.flow-page .stage-footer{padding-top:10px}}
