.password-rules li{display:flex;align-items:center;gap:8px;line-height:1.5}.rule-icon{width:17px;height:17px;display:grid;place-items:center;border:1px solid #cbd9e9;border-radius:50%;flex-shrink:0}.rule-icon>span{width:4px;height:4px;border-radius:50%;background:#91a3ba}.password-rules .met,.password-match.met{color:#187347}.met .rule-icon{background:#e7f6ec;border-color:#a2d4b6}.password-match{display:flex;align-items:center;gap:5px;min-height:18px;font-size:11px;color:#7185a0;margin:0}.password-match.mismatch{color:#b42318}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
